import React from 'react';
import { Stack } from '@fiverr-private/layout_components';
import type { BottomPanelProps } from '../types/RichText';

const RichTextBottomPanel = ({
  children,
  gap = '1',
  dataTrackTag = 'rich_text_bottom_panel',
  ...restProps
}: BottomPanelProps) => (
  <Stack dataTrackTag={dataTrackTag} padding="2" gap={gap} {...restProps}>
    {children}
  </Stack>
);

RichTextBottomPanel.displayName = 'RichTextBottomPanel';

export default RichTextBottomPanel;
