import React, { useCallback, useMemo, forwardRef, useImperativeHandle, useState, FocusEvent } from 'react';
import { Editable, Slate, withReact, ReactEditor } from 'slate-react';
import { type BaseElement, createEditor, type Descendant, Editor, Transforms } from 'slate';
import { withHistory } from 'slate-history';
import { Container } from '@fiverr-private/layout_components';
import { assignInlineVars, tokens } from '@fiverr-private/theme';
import { MarkdownSlateJsonConverter, SlateJsonMarkdownConverter } from '../utils';
import RichTextToolbar from '../RichTextToolbar';
import RichTextElement from '../RichTextElement';
import RichTextLeaf from '../RichTextLeaf';
import type { RichTextEditorProps, EditorRef, GetTextToInsert } from '../types';
import { getBorderColor, getColorByState } from './style';
import { calcMaxHeight, calcMinHeight, customizeOperations, DEFAULT_TOOLBAR, onKeyDown } from './utils';
import { borderFocusWithinVar, container } from './styles.ve.css';

const RichTextEditor = forwardRef<Partial<EditorRef>, RichTextEditorProps>(
  (
    {
      initialValue = '',
      rows = 2,
      disabled,
      autoFocus,
      placeholder,
      onChange,
      onPaste,
      onFocus,
      onBlur,
      onKeyDown: onKeyDownProp,
      isError,
      isSuccess,
      maxHeight: maxHeightProp,
      minHeight: minHeightProp,
      toolbarOptions,
      showToolbar = true,
      children,
      dataTrackTag = 'rich_text_editor',
      dataTrackValue,
    },
    ref
  ) => {
    const editor = useMemo(() => withReact(withHistory(createEditor())), []);
    const [isFocused, setFocused] = useState(false);

    useImperativeHandle(ref, () => ({
      focus: () => {
        ReactEditor.focus(editor);
      },
      blur: () => {
        ReactEditor.blur(editor);
      },
      isFocused: () => ReactEditor.isFocused(editor),
      reset: () => {
        const point = { path: [0, 0], offset: 0 };
        editor.history = { redos: [], undos: [] };
        editor.children.forEach(() => {
          Transforms.delete(editor, { at: [0] });
        });
        editor.children = [
          {
            type: 'paragraph',
            children: [{ text: '' }],
          } as BaseElement,
        ];
        Transforms.setSelection(editor, { anchor: point, focus: point });
      },
      insertText(getTextToInsert: GetTextToInsert) {
        const { text, position: maybePosition } = getTextToInsert(editor);
        const position = maybePosition || 'cursor';
        const renderedText = MarkdownSlateJsonConverter.convert(text);

        switch (position) {
          case 'start':
            editor.insertNodes(renderedText, { at: [0] });
            break;
          case 'end':
            editor.insertNodes(renderedText, { at: [editor.children.length] });
            break;
          case 'cursor':
            editor.insertFragment(renderedText);
            break;
          default:
            editor.insertNodes(renderedText, { at: position });
            break;
        }
      },
      replaceText(text: string) {
        const renderedText = MarkdownSlateJsonConverter.convert(text);

        Transforms.delete(editor, {
          at: {
            anchor: Editor.start(editor, []),
            focus: Editor.end(editor, []),
          },
        });

        if (editor.children.length > 0) {
          Transforms.removeNodes(editor, {
            at: [0],
          });
        }

        Transforms.insertNodes(editor, renderedText);
      },
    }));

    const renderElement = useCallback(
      ({ children, ...props }) => <RichTextElement {...props}>{children}</RichTextElement>,
      []
    );

    const renderLeaf = useCallback(({ children, ...props }) => <RichTextLeaf {...props}>{children}</RichTextLeaf>, []);
    const convertedInitialValue = MarkdownSlateJsonConverter.convert(initialValue);

    customizeOperations(editor);

    const onChangeEditor = (nodes: Descendant[]) => {
      const markdownText = SlateJsonMarkdownConverter.convert(nodes);
      onChange?.(markdownText, nodes);
    };

    const onFocusEditable = (e: FocusEvent<HTMLDivElement>) => {
      setFocused(true);
      onFocus?.(e);
    };

    const onBlurEditable = (e: FocusEvent<HTMLDivElement>) => {
      setFocused(false);
      onBlur?.(e);
    };

    const borderColor = getBorderColor({ disabled, isSuccess, isError, isFocused });
    const colorByState = getColorByState({ isSuccess, isError });
    const maxHeight = calcMaxHeight({ rows, maxHeight: maxHeightProp });
    const minHeight = calcMinHeight({ rows, minHeight: minHeightProp });
    const activeToolbarOptions = { ...DEFAULT_TOOLBAR, ...toolbarOptions };

    return (
      <Slate editor={editor} initialValue={convertedInitialValue} onChange={onChangeEditor}>
        <Container
          width="100%"
          className={container}
          borderWidth="sm"
          pointerEvents={disabled ? 'none' : undefined}
          borderRadius="lg"
          color={disabled ? 'grey_800' : 'grey_1200'}
          backgroundColor={disabled ? 'grey_200' : 'background'}
          borderColor={borderColor}
          outlineColor={{
            default: colorByState,
            focusWithin: colorByState,
          }}
          outlineWidth={{ default: isFocused ? 'sm' : undefined, focusWithin: 'sm' }}
          outlineStyle={{ default: isFocused ? 'solid' : undefined, focusWithin: 'solid' }}
          style={assignInlineVars({ [borderFocusWithinVar]: tokens.colors[colorByState] })}
          dataTrackTag={dataTrackTag}
          dataTrackValue={dataTrackValue}
        >
          {showToolbar && <RichTextToolbar toolbarOptions={activeToolbarOptions} disabled={disabled} />}
          <Container
            paddingY="2"
            paddingX="3"
            overflowY="auto"
            overflowX="hidden"
            maxHeight={maxHeight}
            minHeight={minHeight}
          >
            <Editable
              spellCheck
              renderElement={renderElement}
              renderLeaf={renderLeaf}
              placeholder={placeholder}
              readOnly={disabled}
              disabled={disabled}
              autoFocus={autoFocus}
              onPaste={onPaste}
              onFocus={onFocusEditable}
              onKeyDown={(e) => onKeyDown(e, editor, onKeyDownProp, activeToolbarOptions)}
              onBlur={onBlurEditable}
              rows={rows}
            />
          </Container>
          {children}
        </Container>
      </Slate>
    );
  }
);

RichTextEditor.displayName = 'RichTextEditor';
export default RichTextEditor;
