import React from 'react';
import { ReactEditor, useSlate } from 'slate-react';
import { Node, Transforms } from 'slate';
import { ToggleButton } from '@fiverr-private/button';
import { Tooltip } from '@fiverr-private/tooltip';
import { theme } from '@fiverr-private/theme';
import type { EditorButtonProps, CustomTextElement } from '../../types';
import { TAB_KEY } from '../../constants';
import { getNodeElement, getNodePath } from '../../RichTextEditor/utils.nodes';

interface ActionToggleButtonProps extends EditorButtonProps {
  type: 'indent' | 'outdent';
}

const ActionToggleButton = ({ children, disabled, type, tooltipContent }: ActionToggleButtonProps) => {
  const editor = useSlate();

  const onClick = () => {
    if (type === 'indent' || type === 'outdent') {
      const selected = editor.selection;

      if (selected) {
        const point = selected.anchor.path;
        const parent = editor.parent(point);
        const parentNode = getNodeElement(parent);
        const parentPath = getNodePath(parent);
        const first = editor.first(parentPath);
        const firstNode = getNodeElement<CustomTextElement>(first);
        const firstPath = getNodePath(first);
        const { text } = firstNode;

        const resetSelection = () => {
          const last = editor.end(parentPath);
          Transforms.select(editor, last);
          Transforms.collapse(editor);
        };

        if (parentNode.type === 'list-item') {
          return;
        }

        if (type === 'indent') {
          Transforms.insertNodes(
            editor,
            {
              text: TAB_KEY,
            } as Node,
            { at: [parentPath[0], 0] }
          );
          resetSelection();
        } else if (text.startsWith(TAB_KEY)) {
          editor.insertText(text.substring(TAB_KEY.length), { at: firstPath });
          resetSelection();
        }
      }
    }

    ReactEditor.focus(editor as ReactEditor);
  };

  const isSelected = false;

  return (
    <Tooltip size="sm" content={tooltipContent} offset={theme.numericSpacing['3']}>
      <ToggleButton
        dataTrackTag="rich_text_toolbar_action_button"
        tabIndex={-1}
        disabled={disabled}
        isSelected={isSelected}
        aria-label={type}
        onClick={onClick}
      >
        {children}
      </ToggleButton>
    </Tooltip>
  );
};

ActionToggleButton.displayName = 'ActionToggleButton';
export default ActionToggleButton;
