import React from 'react';
import { useSlate } from 'slate-react';
import { ToggleButton } from '@fiverr-private/button';
import { Tooltip } from '@fiverr-private/tooltip';
import { theme } from '@fiverr-private/theme';
import type { CustomElementType, EditorButtonProps } from '../../types';
import { isBlockActive, toggleBlock } from './utils';

interface BlockButtonProps extends EditorButtonProps {
  type: CustomElementType;
}

const BlockToggleButton = ({ type, children, disabled, tooltipContent }: BlockButtonProps) => {
  const editor = useSlate();

  const isSelected = isBlockActive(editor, type);

  return (
    <Tooltip size="sm" content={tooltipContent} offset={theme.numericSpacing['3']}>
      <ToggleButton
        dataTrackTag="rich_text_toolbar_block_toggle_button"
        tabIndex={-1}
        disabled={disabled}
        isSelected={isSelected}
        aria-label={type}
        onSelectedChanged={() => {
          toggleBlock(editor, type);
        }}
      >
        {children}
      </ToggleButton>
    </Tooltip>
  );
};

BlockToggleButton.displayName = 'BlockToggleButton';
export default BlockToggleButton;
