import type { Descendant } from 'slate';
import { map } from 'lodash';
import type { CustomChildElement, CustomElement, CustomTextElement } from '../types';
import { B_SEPARATOR, I_SEPARATOR, LT_SEPARATOR, U_SEPARATOR } from '../constants';
import { handleIndentationSlateToMarkdown } from './utils';

class SlateJsonMarkdownConverter {
    constructor() {
        this.serializeText = this.serializeText.bind(this);
    }

    public convert(nodes: Descendant[]): string {
        let markdown = '';

        for (const node of nodes) {
            const customElementNode = node as CustomElement;

            markdown += this.customElementToMarkdown(customElementNode);
        }

        return markdown;
    }

    private customElementToMarkdown(customElementNode: CustomElement): string {
        switch (customElementNode.type) {
            case 'paragraph':
                return this.paragraphToMarkdown(customElementNode);
            case 'unordered-list':
                return this.unorderedListToMarkdown(customElementNode);
            case 'numbered-list':
                return this.numberedListToMarkdown(customElementNode);
            default:
                return '';
        }
    }

    private paragraphToMarkdown(paragraphNode: CustomElement): string {
        return `${this.serializeChildren(paragraphNode)}\n`;
    }

    private unorderedListToMarkdown(listItemElement: CustomElement): string {
        return `${map(
            listItemElement.children,
            (listItemChild) => `- ${this.serializeChildren(listItemChild as CustomElement)}\n`
        ).join('')}\n`;
    }

    private numberedListToMarkdown(listItemElement: CustomElement): string {
        return `${map(
            listItemElement.children,
            (listItemChild, index) => `${index + 1}. ${this.serializeChildren(listItemChild as CustomElement)}\n`
        ).join('')}\n`;
    }

    private serializeChildren(node: CustomElement): string {
        return map(node.children, (child) => {
            if (this.isCustomTextElement(child)) {
                return this.serializeText(child);
            } else {
                return this.serializeChildren(child);
            }
        }).join('');
    }

    private addMarkdownSeparator(text: string, separator: string) {
        let startSpaces = '',
            endSpaces = '';
        let charIdx = text.length - 1;

        while (charIdx >= 0 && text[charIdx] === ' ') {
            endSpaces += ' ';
            charIdx--;
        }

        charIdx = 0;
        while (charIdx < text.length && text[charIdx] === ' ') {
            startSpaces += ' ';
            charIdx++;
        }

        return `${startSpaces}${separator}${text.trim()}${separator}${endSpaces}`;
    }

    private serializeText(node: CustomElement | CustomTextElement): string {
        if (this.isCustomTextElement(node)) {
            const { text, bold, italic, underline, lineThrough, url } = node;
            let textResult = handleIndentationSlateToMarkdown(text);
            textResult = textResult
                // If the user already escaped the markdown special characters, we don't need to escape them again
                // This prevents backslashes from being converted to double backslashes
                .replace(/(?<!\\)\*/g, `\\${I_SEPARATOR}`)
                .replace(/(?<!\\)~/g, `\\${LT_SEPARATOR}`)
                .replace(/(?<!\\)\+/g, `\\${U_SEPARATOR}`)
                .replace(/(?<!\\)-/g, `\\-`);
            if (textResult.trim() === '') {
                return textResult;
            }

            if (url) {
                textResult = `[${textResult}](${url})`;
            }

            if (underline && !url) {
                textResult = this.addMarkdownSeparator(textResult, U_SEPARATOR);
            }

            if (lineThrough && !url) {
                textResult = this.addMarkdownSeparator(textResult, LT_SEPARATOR);
            }

            if (bold) {
                textResult = this.addMarkdownSeparator(textResult, B_SEPARATOR);
            }

            if (italic) {
                textResult = this.addMarkdownSeparator(textResult, I_SEPARATOR);
            }

            return textResult;
        }

        const customElementNode = node as CustomElement;

        return map(customElementNode.children, this.serializeText).join('');
    }

    private isCustomTextElement(node: CustomChildElement): node is CustomTextElement {
        return 'text' in node;
    }
}

export default new SlateJsonMarkdownConverter();
