import React from 'react';
import { Stack } from '@fiverr-private/layout_components';
import type { RichTextEditorProps, ToolbarOptions } from '../types';
import BoldToggleButton from './BoldToggleButton';
import ItalicToggleButton from './ItalicToggleButton';
import NumberedListToggleButton from './NumberedListToggleButton';
import UnorderedListToggleButton from './UnorderedListToggleButton';
import UnderlineToggleButton from './UnderlineToggleButton';
import LineThroughToggleButton from './LineThroughToggleButton';
import OutdentToggleButton from './OutdentToggleButton';
import IndentToggleButton from './IndentToggleButton';

interface ToolbarProps extends Pick<RichTextEditorProps, 'disabled' | 'dataTrackTag' | 'dataTrackValue'> {
  toolbarOptions: ToolbarOptions;
}

const MARK_BUTTONS = ['bold', 'italic', 'underline', 'strikeThrough'];
const BLOCK_BUTTONS = ['numberedList', 'unorderedList'];
const ACTION_BUTTONS = ['indent', 'outdent'];

const RichTextToolbar = ({
  disabled,
  toolbarOptions,
  dataTrackTag = 'rich_text_toolbar',
  dataTrackValue,
}: ToolbarProps) => {
  const groupHasButton = (groupOptions: string[]) => {
    let found = false;
    groupOptions.forEach((option) => {
      if (toolbarOptions[option]) {
        found = true;
      }
    });

    return found;
  };

  return (
    <Stack
      borderTopLeftRadius="lg"
      borderTopRightRadius="lg"
      paddingY="2"
      paddingX="2"
      backgroundColor="grey_200"
      gap="2"
      withDivider
      dataTrackTag={dataTrackTag}
      dataTrackValue={dataTrackValue}
    >
      {groupHasButton(MARK_BUTTONS) && (
        <Stack gap="2" width="fit-content">
          {toolbarOptions.bold && <BoldToggleButton disabled={disabled} />}
          {toolbarOptions.italic && <ItalicToggleButton disabled={disabled} />}
          {toolbarOptions.underline && <UnderlineToggleButton disabled={disabled} />}
          {toolbarOptions.strikeThrough && <LineThroughToggleButton disabled={disabled} />}
        </Stack>
      )}
      {groupHasButton(BLOCK_BUTTONS) && (
        <Stack gap="2" width="fit-content">
          {toolbarOptions.unorderedList && <UnorderedListToggleButton disabled={disabled} />}
          {toolbarOptions.numberedList && <NumberedListToggleButton disabled={disabled} />}
        </Stack>
      )}
      {groupHasButton(ACTION_BUTTONS) && (
        <Stack gap="2" width="fit-content">
          {toolbarOptions.indent && <IndentToggleButton disabled={disabled} />}
          {toolbarOptions.outdent && <OutdentToggleButton disabled={disabled} />}
        </Stack>
      )}
    </Stack>
  );
};

RichTextToolbar.displayName = 'RichTextToolbar';
export default RichTextToolbar;
