import { type Types, theme } from '@fiverr-private/theme';
import { RichTextEditorProps } from '../types';

export const getBorderColor = ({
    disabled,
    isSuccess,
    isError,
    isFocused,
}: {
    disabled: RichTextEditorProps['disabled'];
    isSuccess: RichTextEditorProps['isSuccess'];
    isError: RichTextEditorProps['isError'];
    isFocused: boolean;
}): Types.BoxType['borderColor'] => {
    if (disabled) {
        return 'grey_400';
    } else if (isSuccess) {
        return isFocused
            ? 'validationSuccess'
            : {
                  default: 'validationSuccess',
                  hover: 'validationSuccess',
              };
    } else if (isError) {
        return isFocused
            ? 'validationError'
            : {
                  default: 'validationError',
                  hover: 'validationError',
              };
    } else {
        return isFocused
            ? 'grey_1200'
            : {
                  default: 'border',
                  hover: 'grey_1200',
              };
    }
};

export const getColorByState = ({
    isSuccess,
    isError,
}: {
    isSuccess: RichTextEditorProps['isSuccess'];
    isError: RichTextEditorProps['isError'];
}): Types.BorderColor => {
    const { validationError, validationSuccess } = theme.semanticBorderColors;
    if (isSuccess) {
        return validationSuccess;
    } else if (isError) {
        return validationError;
    }

    return 'grey_1200';
};
