import { Editor, Element as SlateElement, Transforms } from 'slate';
import { ReactEditor } from 'slate-react';
import { isEmpty } from 'lodash';
import type { CustomElement, CustomElementType, CustomTextElement } from '../../types';
import { TAB_KEY } from '../../constants';
import { getNodeElement, getNodePath } from '../../RichTextEditor/utils.nodes';

export const LIST_TYPES: CustomElementType[] = ['numbered-list', 'unordered-list'];

const removeIndentationFromListItems = (editor: Editor) => {
    if (editor.selection) {
        const matchArr = Array.from(
            Editor.nodes(editor, {
                at: Editor.unhangRange(editor, editor.selection),
                match: (node) => {
                    if (Editor.isEditor(node)) {
                        return false;
                    }

                    return SlateElement.isElementType(node, 'list-item');
                },
            })
        );

        matchArr.forEach((match) => {
            const initialText = (getNodeElement(match).children[0] as CustomTextElement).text;
            let text = initialText;
            while (text.startsWith(TAB_KEY)) {
                text = text.substring(1);
            }

            if (text !== initialText) {
                editor.insertText(text, { at: [...getNodePath(match), 0] });
            }
        });
    }
};

export const isBlockActive = (editor: Editor, type: CustomElementType) => {
    const { selection } = editor;

    if (!selection) {
        return false;
    }

    const nonCurrentListTypeElements = Array.from(
        Editor.nodes(editor, {
            at: Editor.unhangRange(editor, selection),
            match: (node) => {
                if (Editor.isEditor(node)) {
                    return false;
                }

                if (!SlateElement.isElement(node)) {
                    return false;
                }

                return !SlateElement.isElementType(node, type) && !SlateElement.isElementType(node, 'list-item');
            },
        })
    );

    return isEmpty(nonCurrentListTypeElements);
};

export const toggleBlock = (editor: Editor, type: CustomElementType) => {
    const isActive = isBlockActive(editor, type);
    const isList = LIST_TYPES.includes(type);

    Transforms.unwrapNodes(editor, {
        match: (node): boolean => {
            if (Editor.isEditor(node)) {
                return false;
            }

            return SlateElement.isElementType(node, LIST_TYPES[0]) || SlateElement.isElementType(node, LIST_TYPES[1]);
        },
        split: true,
    });

    let newProperties: Partial<CustomElement>;

    if (isActive) {
        newProperties = {
            type: 'paragraph',
        };
    } else {
        newProperties = {
            type: isList ? 'list-item' : type,
        };
    }

    Transforms.setNodes<SlateElement>(editor, newProperties);

    if (!isActive && isList) {
        const block = { type, children: [] };
        Transforms.wrapNodes(editor, block);
        removeIndentationFromListItems(editor);
    }
    ReactEditor.focus(editor as ReactEditor);
};
