import type { KeyboardEvent } from 'react';
import { type BaseEditor, Editor, Element as SlateElement, Transforms, Path, type NodeEntry } from 'slate';
import type { ReactEditor } from 'slate-react';
import { HistoryEditor } from 'slate-history';
import { isUndefined } from 'lodash';
import { theme } from '@fiverr-private/theme';
import type { RichTextEditorProps, CustomTextElement, CustomElement } from '../types';
import { toggleMark } from '../RichTextToolbar/MarkToggleButton/utils';
import { LIST_TYPES, toggleBlock } from '../RichTextToolbar/BlockToggleButton/utils';
import { getNodeElement, getNodePath } from './utils.nodes';

const LINE_HEIGHT = parseInt(theme.bodyLineHeights.b_md, 10);
const PADDING_HEIGHT = 16;
const SPACE = ' ';
const HTTPS = 'https://';
const urlPattern = new RegExp(
    '^(https?:\\/\\/)?' + // validate protocol
        '((([a-z\\d]([a-z\\d-]*[a-z\\d])*)\\.)+[a-z]{2,}|' + // validate domain name
        '((\\d{1,3}\\.){3}\\d{1,3}))' + // validate OR ip (v4) address
        '(\\:\\d+)?(\\/[-a-z\\d%_.~+]*)*' + // validate port and path
        '(\\?[;&a-z\\d%_.~+=-]*)?' + // validate query string
        '(\\#[-a-z\\d_]*)?$', // validate fragment locator
    'i'
);

export const DEFAULT_TOOLBAR: RichTextEditorProps['toolbarOptions'] = {
    bold: true,
    italic: true,
    underline: false,
    strikeThrough: false,
    numberedList: true,
    unorderedList: true,
    indent: false,
    outdent: false,
};

export const calcMaxHeight = ({
    rows,
    maxHeight,
}: Pick<RichTextEditorProps, 'rows' | 'maxHeight'>): RichTextEditorProps['maxHeight'] => {
    if (maxHeight) {
        return maxHeight;
    }
    if (rows && rows !== -1) {
        return `${rows * LINE_HEIGHT + PADDING_HEIGHT}px`;
    }
};

export const calcMinHeight = ({
    rows,
    minHeight,
}: Pick<RichTextEditorProps, 'rows' | 'minHeight'>): RichTextEditorProps['minHeight'] => {
    if (minHeight) {
        return minHeight;
    }
    if (rows && rows !== -1) {
        return `${rows * LINE_HEIGHT + PADDING_HEIGHT}px`;
    }
};

const hasValidUrl = (urlString?: string | null) => {
    if (!urlString) {
        return false;
    }
    const parts = urlString.split(SPACE);

    let found = false;
    parts.forEach((part) => {
        if (urlPattern.test(part)) {
            found = true;
        }
    });

    return found;
};

const isFullLink = (text: string) => text.startsWith('http://') || text.startsWith('https://');

const handleLinkEditing = (text: string, editor: ReactEditor & BaseEditor, isEnter?: boolean) => {
    let { selection } = editor;
    const prevLinkNode = editor.previous();
    const prevLinkElement = (prevLinkNode && getNodeElement<CustomTextElement>(prevLinkNode)) || { text: '' };
    const linkNode = selection && editor.node(selection);
    const linkElement = (linkNode && getNodeElement<CustomTextElement>(linkNode)) || { text: '' };
    const isSpaceOnLinkEnd = text === SPACE && linkElement.url && linkElement.text.endsWith(SPACE);
    const isSpaceOnLinkStart = text === SPACE && linkElement.url && linkElement.text.startsWith(SPACE);

    const handleExistingLinkRemainsValid = (linkNode: NodeEntry | null, linkElement: CustomTextElement) => {
        if (linkNode) {
            Transforms.setNodes<CustomTextElement>(
                editor,
                { url: isFullLink(linkElement.text) ? linkElement.text : `${HTTPS}${linkElement.text}` },
                {
                    at: getNodePath(linkNode),
                }
            );
        }
    };

    if (isEnter && linkElement.url && prevLinkNode && prevLinkElement.url) {
        if (urlPattern.test(prevLinkElement.text)) {
            handleExistingLinkRemainsValid(prevLinkNode, prevLinkElement);
        } else {
            Transforms.setNodes<CustomTextElement>(editor, { url: undefined }, { at: prevLinkNode[1] });
        }
    }

    if (linkElement.url && urlPattern.test(linkElement.text)) {
        handleExistingLinkRemainsValid(linkNode, linkElement);
        return;
    }

    Transforms.setNodes<CustomTextElement>(
        editor,
        { url: undefined },
        {
            match: (node) => {
                if (Editor.isEditor(node)) {
                    return false;
                }

                if (SlateElement.isElement(node)) {
                    return false;
                }

                return !isUndefined((node as CustomTextElement)?.url);
            },
        }
    );

    selection = editor.selection;
    const node = selection && editor.node(selection);
    const nodeElement = (node && getNodeElement<CustomTextElement>(node)) || { text: '' };
    const { text: nodeText, ...formatters } = nodeElement;
    const nodeAt = node && node[1];

    if (nodeAt && nodeText && hasValidUrl(nodeText) && selection) {
        const getLink = (text: string) => ({
            ...formatters,
            url: isFullLink(text) ? text : `${HTTPS}${text}`,
            text,
        });

        const parts = nodeText.split(SPACE);
        let prevNodeIsUrl = false;
        const nodes = parts.map((part, idx) => {
            if (hasValidUrl(part)) {
                prevNodeIsUrl = true;
                return getLink(part);
            } else {
                const nextNodeIsUrl = idx < parts.length - 1 && hasValidUrl(parts[idx + 1]);
                const text = `${prevNodeIsUrl && !part.startsWith(SPACE) ? SPACE : ''}${part}${
                    nextNodeIsUrl || idx < parts.length - 1 ? SPACE : ''
                }`;
                prevNodeIsUrl = false;
                return { text, ...formatters };
            }
        });

        Transforms.removeNodes(editor, {
            at: nodeAt,
        });
        Transforms.insertNodes(editor, nodes, {
            at: nodeAt,
        });

        const nodeToSelect = editor.next({ at: nodeAt });
        const alternativeNodeToSelect = editor.node(nodeAt);

        if (isSpaceOnLinkEnd) {
            let node = alternativeNodeToSelect;
            if (nodeToSelect) {
                node = Path.isAfter(nodeToSelect[1], alternativeNodeToSelect[1])
                    ? nodeToSelect
                    : alternativeNodeToSelect;
            }

            const nodeElement = getNodeElement<CustomTextElement>(node);
            const isLink = !!nodeElement.url;

            Transforms.select(editor, {
                path: getNodePath(node),
                offset: nodeElement.text.length,
            });
            if (isLink) {
                Transforms.move(editor, { unit: 'character', distance: 1 });
            } else if (nodeElement.text !== SPACE) {
                Transforms.move(editor, {
                    unit: 'character',
                    reverse: true,
                    distance: nodeElement.text.length - 1,
                });
            }
        } else if (isSpaceOnLinkStart) {
            let node = alternativeNodeToSelect;
            if (nodeToSelect) {
                node = Path.isBefore(getNodePath(nodeToSelect), getNodePath(alternativeNodeToSelect))
                    ? nodeToSelect
                    : alternativeNodeToSelect;
            }
            Transforms.select(editor, {
                path: getNodePath(node),
                offset: getNodeElement<CustomTextElement>(node).text.length,
            });
        } else {
            const node = nodeToSelect || alternativeNodeToSelect;
            Transforms.select(editor, {
                path: getNodePath(node),
                offset: getNodeElement<CustomTextElement>(node).text.length,
            });
        }
    }
};

export const customizeOperations = (editor: ReactEditor & BaseEditor) => {
    const { insertText } = editor;
    editor.insertText = (text, options) => {
        insertText(text, options);
        handleLinkEditing(text, editor);
    };
};

export const onKeyDown = (
    e: KeyboardEvent<HTMLDivElement>,
    editor: ReactEditor & HistoryEditor & BaseEditor,
    onKeyDown: RichTextEditorProps['onKeyDown'],
    activeToolbarOptions: RichTextEditorProps['toolbarOptions'] = {}
) => {
    const { key, ctrlKey, metaKey, shiftKey } = e;
    const isBackspaceKey = key === 'Backspace';
    const isDeleteKey = key === 'Delete';
    const isEnter = key === 'Enter';
    const isCtrlKey = ctrlKey || metaKey;
    const isSpaceKey = key === ' ';

    if ((isBackspaceKey || isDeleteKey || isEnter) && editor.selection) {
        const node = editor.node(editor.selection);
        if (getNodeElement<CustomTextElement>(node).text) {
            setTimeout(() => {
                handleLinkEditing('', editor, isEnter);
            }, 0);
        }
    }

    if (isBackspaceKey && editor.selection) {
        const node = editor.node(editor.selection);
        const nodePath = getNodePath(node);
        if (nodePath.length > 0) {
            const parent = editor.parent(nodePath);
            const parentNode = getNodeElement(parent);
            if (
                parentNode.type === 'list-item' &&
                editor.selection.anchor.offset === 0 &&
                editor.selection.focus.offset === 0
            ) {
                e.preventDefault();
                const listNode = getNodeElement(editor.parent(getNodePath(parent)));
                toggleBlock(editor, listNode.type);
            }
        }
    }

    if (isEnter && editor.selection) {
        const node = editor.node(editor.selection);
        const nodePath = getNodePath(node);
        if (nodePath.length > 0) {
            const listItemNode = getNodeElement(editor.parent(nodePath));
            if (getNodeElement<CustomTextElement>(node).text === '' && listItemNode.type === 'list-item') {
                e.preventDefault();
                const listItemNode = editor.parent(node[1]);
                const listNode = getNodeElement(editor.parent(getNodePath(listItemNode)));
                toggleBlock(editor, listNode.type);
            }
        }
    }

    if (isCtrlKey) {
        switch (key) {
            case 'b':
                if (activeToolbarOptions.bold) {
                    toggleMark(editor, 'bold');
                }
                break;
            case 'i':
                if (activeToolbarOptions.italic) {
                    toggleMark(editor, 'italic');
                }
                break;
            case 'u':
                if (activeToolbarOptions.underline) {
                    toggleMark(editor, 'underline', 'lineThrough', true);
                }
                break;
            case 'x':
                if (activeToolbarOptions.strikeThrough && shiftKey) {
                    toggleMark(editor, 'lineThrough', 'underline', true);
                }
                break;
            case 'z':
                if (shiftKey) {
                    HistoryEditor.redo(editor);
                } else {
                    HistoryEditor.undo(editor);
                }
                break;
            default:
                break;
        }
    }

    if (isSpaceKey && editor.selection) {
        const node = editor.node(editor.selection);
        const path = getNodePath(node);
        const isFirstLevelNode = path.length === 2 && path[1] === 0;
        const { text } = getNodeElement<CustomTextElement>(node);

        if (text && isFirstLevelNode) {
            if (text === '1.' && activeToolbarOptions.numberedList) {
                Transforms.delete(editor, { at: { anchor: { path, offset: 0 }, focus: { path, offset: 2 } } });
                toggleBlock(editor, 'numbered-list');
                e.preventDefault();
            } else if (text === '-' && activeToolbarOptions.unorderedList) {
                Transforms.delete(editor, { at: { anchor: { path, offset: 0 }, focus: { path, offset: 1 } } });
                toggleBlock(editor, 'unordered-list');
                e.preventDefault();
            }
        }
    }

    // validate of valid markup after operations - fixes bugs: 1) list-item has no list as a parent, 2) paragraph is child of list
    setTimeout(() => {
        if (editor.selection) {
            const node = editor.node(editor.selection);
            if (node[1].length) {
                const parent = editor.parent(getNodePath(node));
                const parentNode = getNodeElement(parent);
                if (parentNode.type === 'list-item') {
                    const parentPath = getNodePath(parent);
                    if (parentPath.length) {
                        const parentOfParent = editor.parent(parentPath);
                        if (!LIST_TYPES.includes(getNodeElement(parentOfParent).type)) {
                            const props: Partial<CustomElement> = { type: 'paragraph' };
                            Transforms.setNodes(editor, props, { at: parentPath });
                        }
                    } else {
                        const props: Partial<CustomElement> = { type: 'paragraph' };
                        Transforms.setNodes(editor, props, { at: parentPath });
                    }
                } else if (parentNode.type === 'paragraph' && getNodePath(parent).length) {
                    const parentPath = getNodePath(parent);
                    const parentOfParent = editor.parent(parentPath);
                    if (LIST_TYPES.includes(getNodeElement(parentOfParent).type)) {
                        const props: Partial<CustomElement> = { type: 'list-item' };
                        Transforms.setNodes(editor, props, { at: parentPath });
                    }
                }
            }
        }
    }, 0);

    onKeyDown?.(e);
};
