import React from 'react';
import { useSlate } from 'slate-react';
import { ToggleButton } from '@fiverr-private/button';
import { Tooltip } from '@fiverr-private/tooltip';
import { theme } from '@fiverr-private/theme';
import type { CustomTextFormat, EditorButtonProps } from '../../types';
import { isMarkActive, toggleMark } from './utils';

interface MarkToggleButtonProps extends EditorButtonProps {
  format: CustomTextFormat;
  dependantFormat?: CustomTextFormat;
  disabledOnLinks?: boolean;
}

const MarkToggleButton = ({
  format,
  children,
  disabled,
  dependantFormat,
  tooltipContent,
  disabledOnLinks = false,
  dataTrackTag = 'rich_text_toolbar_mark_toggle_button',
}: MarkToggleButtonProps) => {
  const editor = useSlate();

  const { isActive, isDisabled } = isMarkActive(editor, format, disabledOnLinks);

  return (
    <Tooltip size="sm" content={tooltipContent} offset={theme.numericSpacing['3']}>
      <ToggleButton
        dataTrackTag={dataTrackTag}
        tabIndex={-1}
        disabled={disabled || isDisabled}
        isSelected={isActive}
        aria-label={format}
        onSelectedChanged={() => {
          toggleMark(editor, format, dependantFormat, disabledOnLinks);
        }}
      >
        {children}
      </ToggleButton>
    </Tooltip>
  );
};

MarkToggleButton.displayName = 'MarkToggleButton';
export default MarkToggleButton;
