import { Editor, Element as SlateElement, Transforms } from 'slate';
import { isEmpty, isEqual, isUndefined } from 'lodash';
import { ReactEditor } from 'slate-react';
import type { CustomTextElement, CustomTextFormat } from '../../types';
import { getNodeElement, getNodePath } from '../../RichTextEditor/utils.nodes';

const addMark = (editor: Editor, format: CustomTextFormat) => {
    const { selection } = editor;
    const nodes = selection && Array.from(editor.nodes({ at: selection }));

    nodes?.forEach((node) => {
        const isUrl = node && getNodeElement<CustomTextElement>(node).url;
        if (isUrl) {
            Transforms.setNodes(
                editor,
                { [format]: true },
                {
                    at: getNodePath(node),
                    match: (node) => {
                        if (Editor.isEditor(node)) {
                            return false;
                        }

                        if (SlateElement.isElement(node)) {
                            return false;
                        }

                        return !isUndefined((node as CustomTextElement).url);
                    },
                }
            );
        }
    });

    Editor.addMark(editor, format, true);
};

const removeMark = (editor: Editor, format: CustomTextFormat) => {
    const { selection } = editor;
    const nodes = selection && Array.from(editor.nodes({ at: selection }));

    nodes?.forEach((node) => {
        const isUrl = node && getNodeElement<CustomTextElement>(node).url;
        if (isUrl) {
            Transforms.setNodes(
                editor,
                { [format]: undefined },
                {
                    at: getNodePath(node),
                    match: (node) => {
                        if (Editor.isEditor(node)) {
                            return false;
                        }

                        if (SlateElement.isElement(node)) {
                            return false;
                        }

                        return !isUndefined((node as CustomTextElement).url);
                    },
                }
            );
        }
    });

    Editor.removeMark(editor, format);
};

export const toggleMark = (
    editor: Editor,
    format: CustomTextFormat,
    dependantFormat?: CustomTextFormat,
    disableOnLinks?: boolean
) => {
    const { isActive } = isMarkActive(editor, format, disableOnLinks);

    if (isActive) {
        removeMark(editor, format);
    } else {
        addMark(editor, format);
        if (dependantFormat) {
            removeMark(editor, dependantFormat);
        }
    }

    ReactEditor.focus(editor as ReactEditor);
};

export const isMarkActive = (editor: Editor, format: CustomTextFormat, disabledOnLinks?: boolean) => {
    const { selection } = editor;

    if (!selection) {
        return { isActive: false, isDisabled: false };
    }

    const hasSelectionRange = !isEqual(selection.focus, selection.anchor);
    if (hasSelectionRange) {
        const currentFormatNodes = Array.from(
            Editor.nodes(editor, {
                at: Editor.unhangRange(editor, selection),
                match: (node) => {
                    if (Editor.isEditor(node)) {
                        return false;
                    }

                    if (SlateElement.isElement(node)) {
                        return false;
                    }

                    return (
                        SlateElement.matches(node as unknown as SlateElement, { [format]: true }) &&
                        node.text.trim() !== ''
                    );
                },
            })
        );

        const allNonEmptyTextNodes = Array.from(
            Editor.nodes(editor, {
                at: Editor.unhangRange(editor, selection),
                match: (node) => {
                    if (Editor.isEditor(node)) {
                        return false;
                    }

                    if (SlateElement.isElement(node)) {
                        return false;
                    }

                    return node.text.trim() !== '';
                },
            })
        );

        const isActive = !isEmpty(currentFormatNodes) && allNonEmptyTextNodes.length === currentFormatNodes.length;

        if (disabledOnLinks) {
            const allTextNodes = Array.from(
                Editor.nodes(editor, {
                    at: Editor.unhangRange(editor, selection),
                    match: (node) => {
                        if (Editor.isEditor(node)) {
                            return false;
                        }

                        return !SlateElement.isElement(node);
                    },
                })
            );
            const allLinkNodes = Array.from(
                Editor.nodes(editor, {
                    at: Editor.unhangRange(editor, selection),
                    match: (node) => {
                        if (Editor.isEditor(node)) {
                            return false;
                        }

                        if (SlateElement.isElement(node)) {
                            return false;
                        }

                        return !isUndefined((node as CustomTextElement)?.url);
                    },
                })
            );

            return {
                isActive,
                isDisabled: !isEmpty(allLinkNodes) && allLinkNodes.length === allTextNodes.length,
            };
        }

        return {
            isActive,
            isDisabled: false,
        };
    }

    const node = editor.node(selection);
    const isDisabled = disabledOnLinks && !isUndefined(getNodeElement<CustomTextElement>(node).url);
    const isActive = !!Editor.marks(editor)?.[format];

    return { isActive: isDisabled ? false : isActive, isDisabled };
};
